// g14Paragraphs は文を 1 つずつ段落にした文書 (1 文が 1 行になる)。
func g14Paragraphs(groups ...[]string) string {
	var all []string
	for _, g := range groups {
		all = append(all, g...)
	}
	return strings.Join(all, "\n\n") + "\n"
}

